import{t as e}from"./jsx-runtime-D3jfb0Ew.js";import{D as t,h as n,r,s as i,t as a}from"./index-DYHRBh87.js";var o={tollFree:{label:{en:`Toll-free helpline`,hi:`टोल फ्री हेल्पलाइन`},value:``},whatsapp:{label:{en:`WhatsApp`,hi:`व्हाट्सएप`},value:``,digits:``.replace(/[^\d]/g,``)},csc:{label:{en:`Common Service Centre`,hi:`कॉमन सर्विस सेंटर`},value:``}},s=e(),c=[{id:`official`,q:{en:`Is this an official government website?`,hi:`क्या यह आधिकारिक सरकारी वेबसाइट है?`,mr:`हे सरकारी वेबसाइट आहे का?`,ta:`இது அரசு அரசு இணையதளமா?`,te:`ఇది ప్రభుత్వ ప్రభుత్వ వెబ్‌సైట్ అయితేనా?`,bn:`এটি কি একটি সরকারি সরকারি ওয়েবসাইট?`},a:{en:`No. Sahayak Seva is an independent service that explains government schemes. Nothing here is a submission to any government department, and we cannot accept an application on your behalf. Always confirm details on the official portal before you act on them — every scheme guide here links to the relevant official site.`,hi:`नहीं। सहायक सेवा एक स्वतंत्र सेवा है जो सरकारी योजनाओं की व्याख्या करती है। यहाँ कुछ भी किसी सरकारी विभाग में जमा नहीं है, और हम आपकी ओर से आवेदन स्वीकार नहीं कर सकते। कार्रवाई से पहले हमेशा आधिकारिक पोर्टल पर विवरण की पुष्टि करें — यहाँ हर योजना गाइड संबंधित आधिकारिक साइट से जुड़ी है।`,mr:`नाही. सहाय्य सेवा ही स्वतंत्र सेवा आहे जी सरकारी योजनांचे स्पष्टीकरण करते. येथे काहीही सरकारी विभागाकडे सादर केलेले नाही, आणि आम्ही तुमच्या वतीने अर्ज स्वीकारू शकत नाही. कृती करण्यापूर्वी नेहमी अधिकृत पोर्टलवर तपासा — येथील प्रत्येक योजना मार्गदर्शन संबंधित अधिकृत साइटशी जोडलेले आहे.`,ta:`இல்லை. சஹாயக் சேவை என்பது அரசு திட்டங்களை விளக்கும் சுயேச்சையான சேவை. இங்கு எதுவும் அரசு அமைப்பிடம் சமர்ப்பிக்கப்படுவதில்லை, உங்கள் செயலில் நாங்கள் விண்ணப்பம் ஏற்க முடியாது. செயல்படுவதற்கு முன் அதிகாரப்பூர்வ போர்ட்டலில் உறுதிப்படுத்துங்கள் — இங்குள்ள ஒவ்வொரு திட்ட வழிகாட்டலும் தொடர்புடைய அதிகாரப்பூர்வ தளத்தைச் சுட்டுகிறது.`,te:`కాదు. సహాయక్ సేవ ప్రభుత్వ పథకాలను వివరించే స్వతంత్ర సేవ. ఇక్కడ ఏదీ ప్రభుత్వ విభాగానికి సమర్పణ కాదు, మరియు మీ తరఫున దరఖాస్తు అందించలేము. చర్య తీసుకోవడానికి ముందు అధికారిక పోర్టల్‌లో నిర్ధారించండి — ఇక్కడి ప్రతి పథక మార్గదర్శకం సంబంధిత అధికారిక సైట్‌కు లింక్ చేస్తుంది.`,bn:`না৾ সহায়ক সেবা একটি স্বাধীন সেবা যা সরকারি প্রকল্প ব্যাখ্যা করে৾ এখানে কিছুই কোনো সরকারি বিভাগে জমা হয় না, এবং আমরা আপনার পক্ষে আবেদন নিতে পারি না৾ কাজ করার আগে সবসময় অফিসিয়াল পোর্টালে যাচাই করুন — এখানকার প্রতিটি প্রকল্প নির্দেশিকা প্রাসঙ্গিক অফিসিয়াল সাইটে যুক্ত৾`}},{id:`account`,q:{en:`Do I need to create an account?`,hi:`क्या मुझे अकाउंट बनाने की जरूरत है?`,mr:`मला खाते तयार करण्याची गरज आहे का?`,ta:`கணக்கு உருவாக்க வேண்டுமா?`,te:`ఖాతా సృష్టించాలా?`,bn:`আমাকে কি অ্যাকাউন্ট খুলতে হবে?`},a:{en:`No. The app works without any login. A random device identifier is created on your phone during first use and is the only thing that links your conversations together. We do not ask for your name, phone number, Aadhaar, or any other identity detail in this version.`,hi:`नहीं। ऐप बिना किसी लॉगिन के काम करता है। पहली बार उपयोग पर आपके फोन में एक यादृच्छिक डिवाइस पहचान बनती है, और यही एकमात्र चीज़ है जो आपकी बातचीत को जोड़ती है। इस संस्करण में हम आपका नाम, फोन नंबर, आधार या कोई अन्य पहचान विवरण नहीं माँगते।`,mr:`नाही. अ‍ॅप कोणत्याही लॉगिनशिवाय चालते. पहिल्या वापरल्यावर तुमच्या फोनवर एक काहीतरीतरील डिव्हाइस ओळख तयार होते, आणि तीच एकच गोष्ट तुमच्या संवादांना जोडते. या आवृत्तीत आम्ही तुमचे नाव, फोन नंबर, आधार किंवा इतर ओळख मागित नाही.`,ta:`இல்லை. எந்த உள்நுழைவும் இல்லாமல் செயல் செய்கிறது. முதல் பயன்பாட்டின்போது உங்கள் தொலைபேசியில் ஒரு சீரற்ற சாதன அடையாளம் உருவாகிறது, அதுவே உங்கள் உரையாடல்களை இணைக்கும் ஒரே விஷயம். இந்தப் பதிப்பில் உங்கள் பெயர், தொலைபேசி எண், ஆதார் அல்லது வேறு அடையாள விவரங்களைக் கேட்பதில்லை.`,te:`కాదు. యాప్ ఏ లాగిన్ లేకుండానే పనిచేస్తుంది. మొదటి సారి ఉపయోగం సమయంలో మీ ఫోన్‌లో ఒక యాదృచ్ఛిక పరికర గుర్తింపు కల్గుతుంది, అదే మీ సంభాషణలను కలిపే ఏకైకా విషయం. ఈ సంస్కరణలో మీ పేరు, ఫోన్ నంబర్, ఆధార్ లేదా ఇతర గుర్తింపు వివరాలను మేము అడగం లేదు.`,bn:`না৾ অ্যাপ কোনো লগইন ছাড়াই কাজ করে৾ প্রথম ব্যবহারের সময় আপনার ফোনে একটি এলোমেলো ডিভাইস শনাক্তকারী তৈরি হয়, এবং এটিই আপনার কথোপকথনগুলোকে যুক্ত করে এমন একমাত্র জিনিস৾ এই সংস্করণে আমরা আপনার নাম, ফোন নম্বর, আধার বা অন্য কোনো পরিচয়ের তথ্য চাই না৾`}},{id:`offline`,q:{en:`Does it work without a network connection?`,hi:`क्या यह बिना नेटवर्क के काम करता है?`,mr:`हे नेटवर्कशिवाय कार्य करते का?`,ta:`இணைப்பு இல்லாமல் இது வேலை செய்கிறதா?`,te:`నెట్‌వర్క్ లేకుండా పనిచేస్తుందా?`,bn:`এটি কি নেটওয়ার্ক ছাড়াই কাজ করে?`},a:{en:`Yes, and this is the main design goal. Once the app has loaded, all scheme guides are stored on your device and every one of them is readable with the network switched off. You can read eligibility, documents, steps, and office locations entirely offline. Anything you type is saved on the device and sent automatically when a connection returns — the Sync status page shows exactly what is still waiting.`,hi:`हां, और यही इस ऐप का मुख्य लक्ष्य है। ऐप एक बार लोड होने के बाद सभी योजना गाइड आपके डिवाइस पर सहेजे जाते हैं और नेटवर्क बंद होने पर भी सब पढ़े जा सकते हैं। आप पात्रता, दस्तावेज़, चरण और कार्यालय की जानकारी पूरी तरह ऑफ़लाइन पढ़ सकते हैं। आप जो लिखते हैं वह डिवाइस पर सुरक्षित रहता है और कनेक्शन लौटने पर अपने आप भेज दिया जाता है — सिंक स्थिति पेज दिखाता है कि क्या बाकी है।`,mr:`हो, आणि हेच या अ‍ॅपचे मुख्य ध्येद्य आहे. अ‍ॅप एकदा लोड झाल्यावर सर्व योजना मार्गदर्शन तुमच्या डिव्हाइसवर साठवले जातात आणि नेटवर्क बंद असतानाही सर्व वाचता येते. तुम्ही पात्रता, कागदपत्रे, पायऱ्या आणि कार्यालयाची माहिती पूर्णपणे ऑफलाइन वाचू शकता. तुम्ही जे लिहिले ते डिव्हाइसवर सुरक्षित राहते आणि कनेक्शन परत आल्यावर आपोआप पाठवले जाते — सिंक स्थिती पान काय प्रलंबित आहे ते दाखवते.`,ta:`ஆம், மேலும் இதுவே இந்தச் செயலியின் முதன்மை நோக்கம். செயலி ஒருமுறை ஏற்றிய பின் அனைத்துத் திட்ட வழிகாட்டல்களும் உங்கள் சாதனத்தில் சேமிக்கப்பட்டு, இணைப்பு இல்லாமலும் அனைத்தையும் படிக்கலாம். அரசு செய்திகள், ஆவணங்கள், படிகள், அலுவலக முகவரை ஆஃப்லைனில் முழுமையாகப் படிக்கலாம். நீங்கள் தட்டச்சு செய்பது சாதனத்தில் சேமிக்கப்பட்டு, இணைப்பு மீண்டும் வந்ததும் தானாக அனுப்பப்படும் — சிங்க் நிலை பக்கம் என்ன மட்டும் நிலுவையில் உள்ளது என்பதைக் காட்டுகிறது.`,te:`అవును, మరియు ఇదే ఈ యాప్ ప్రధాన లక్ష్యం. యాప్ ఒకసారి లోడ్ అయిన తర్వాత అన్ని పథక మార్గదర్శకాలు మీ పరికరంలో నిల్వ అవుతాయి, నెట్‌వర్క్ లేకుండానే అన్నీ చదవవచ్చు. అర్హత, పత్రాలు, దశలు, కార్యాలయ వివరాలన్నీ పూర్తిగా ఆఫ్‌లైన్‌లో చదవవచ్చు. మీరు టైప్ చేసినది పరికరంలో సేవ్ అవుతుంది, కనెక్షన్ తిరిగి వచ్చిన వెంటనే ఆటోమేటిక్‌గా పంపబడుతుంది — సింక్ స్థితి పేజీ ఏం బాకీ ఉందో చూపిస్తుంది.`,bn:`হ্যাঁ, এবং এটিই এই অ্যাপের প্রধান লক্ষ্য৾ অ্যাপ একবার লোড হলে সব প্রকল্প নির্দেশিকা আপনার ডিভাইসে সংরক্ষিত হয় এবং নেটওয়ার্ক বন্ধ থাকলেও সব পড়া যায়৾ আপনি অযোগ্যতা, নথি, ধাপ এবং দপ্তরের তথ্য সম্পূর্ণ অফলাইনে পড়তে পারেন৾ আপনি যা টাইপ করেন তা ডিভাইসে সংরক্ষিত থাকে এবং সংযোগ ফিরে এলে স্বয়ংক্রিয়ভাবে পাঠানো হয় — সিঙ্ক অবস্থা পেজ কী বাকি আছে তা দেখায়৾`}},{id:`privacy`,q:{en:`What happens to my data?`,hi:`मेरे डेटा के साथ क्या होता है?`,mr:`माझ्या डेटाचे काय होते?`,ta:`எனது தரவுக்கு என்ன நடக்கும்?`,te:`నా డేటాకు ఏమి జరుగుతుంది?`,bn:`আমার ডেটার কী হয়?`},a:{en:`Scheme guides and your message queue are stored in this browser's local database (IndexedDB) on your own device. This version stores them in plain text — they are not encrypted at rest on your device, so anyone with access to your unlocked device and its browser data could read them. They are transmitted to our server only when a sync actually happens, and are tied to a random device identifier rather than to you. We do not sell or share this data, and Phase 1 collects no personal identifying information at all.`,hi:`योजना गाइड और आपका संदेश कतार आपके डिवाइस के स्थानीय डेटाबेस (IndexedDB) में संग्रहीत रहते हैं। इस संस्करण में वे सादे टेक्स्ट में संग्रहीत होते हैं — डिवाइस पर एन्क्रिप्ट नहीं किए जाते — इसलिए आपके अनलॉक डिवाइस और ब्राउज़र डेटा तक पहुंच रखने वाला कोई भी व्यक्ति उन्हें पढ़ सकता है। ये सिर्फ वास्तव में सिंक होने पर ही हमारे सर्वर पर भेजे जाते हैं, और एक यादृच्छिक डिवाइस पहचान से जुड़े होते हैं, आपसे नहीं। हम यह डेटा नहीं बेचते और साझा नहीं करते, और चरण 1 में कोई व्यक्तिगत पहचान जानकारी एकत्र नहीं की जाती।`,mr:`योजना मार्गदर्शने आणि तुमचा संदेश रांग तुमच्या डिव्हाइसच्या स्थानिक डेटाबेसमध्ये (IndexedDB) साठवलेली असतात. या आवृत्तीत ती साध्या मजकूरात साठवली जातात — डिव्हाइसवर एन्क्रिप्ट केलेली नाहीत — म्हणून तुमचा अनलॉक केलेला डिव्हाइस आणि त्याचा ब्राउझर डेटा ज्याला पोहोचता येईल तो ती वाचू शकतो. ती फक्त खरोखर सिंक झाल्यावरच आमच्या सर्व्हरवर पाठवली जातात आणि काहीतरीतरील डिव्हाइस ओळखीशी जोडलेली असतात, तुमच्याशी नाही. आम्ही हा डेटा विकत घेत नाही किंवा शेअर करत नाही, आणि टप्पा 1 मध्ये कोणतीही वैयक्तिक ओळख माहिती गोळा केली जात नाही.`,ta:`திட்ட வழிகாட்டல்களும் உங்கள் செய்தி வரிசையும் உங்கள் சாதனத்தின் உள்ளைத் தரவுத்தளத்தில் (IndexedDB) சேமிக்கப்படுகின்றன. இந்தப் பதிப்பில் அவை சாதாரண உரையாகச் சேமிக்கப்படுகின்றன — சாதனத்தில் குறியாக்கப்படுவதில்லை — எனவே உங்கள் திறந்த சாதனம் மற்றும் அதன் உலாவி தரவுக்கு அணுகும் யாரும் அவற்றைப் படிக்க முடியும். உண்மையில் ஒரு ஒட்சி நடைபெறும்போதுதான் அவை எங்கள் சர்வருக்கு அனுப்பப்படுகின்றன, அவை சீரற்ற சாதன அடையாளத்துடன் இணைக்கப்பட்டுள்ளன, உங்களுடன் அல்ல. இந்தத் தரவை நாங்கள் விற்பதில்லை அல்லது பகிர்ந்துகொள்வதில்லை, மேலும் கட்டம் 1 இல் எந்த தனிப்பட்ட அடையாளத் தகவலும் சேகரிக்கப்படுவதில்லை.`,te:`పథక మార్గదర్శకాలు మరియు మీ సందేశ క్యూ మీ పరికరం లోకల్ డేటాబేస్‌లో (IndexedDB) నిల్వ అవుతాయి. ఈ సంస్కరణలో అవి సాధారణ పాఠ్యంగా నిల్వ అవుతాయి — పరికరంలో ఎన్‌క్రిప్ట్ చేయబడవు — అందుకే మీ అన్‌లాక్ చేసిన పరికరం మరియు దాని బ్రౌజర్ డేటాకు చేరుకోగల ఎవరైనా వాటిని చదవగలరు. అవి నిజంగా సింక్ అయ్యేటప్పుడే మా సర్వర్‌కు పంపబడతాయి, మరియు యాదృచ్ఛిక పరికర గుర్తింపుతో జుడతాయి, మితో కాదు. మేము ఈ డేటాను అమ్మము లేదా పంచుకోము, మరియు దశ 1 లో వ్యక్తిగత గుర్తింపు సమాచారాన్ని సేకరించం లేదు.`,bn:`প্রকল্প নির্দেশিকা এবং আপনার বার্তা সারি আপনার ডিভাইসের স্থানীয় ডেটাবেসে (IndexedDB) সংরক্ষিত থাকে৾ এই সংস্করণে সেগুলো সরল লেখায় সংরক্ষিত থাকে — ডিভাইসে এনক্রিপ্ট করা থাকে না — তাই আপনার আনলক করা ডিভাইস এবং এর ব্রাউজার ডেটায় প্রবেশাধিকার পাওয়া যে কেউ সেগুলো পড়তে পারে৾ সত্যিকারের সিঙ্ক ঘটলেই কেবল সেগুলো আমাদের সার্ভারে পাঠানো হয় এবং সেগুলো একটি এলোমেলো ডিভাইস শনাক্তকারীর সাথে যুক্ত থাকে, আপনার সাথে নয়৾ আমরা এই ডেটা বিক্রি বা ভাগ করি না, এবং ধাপ 1-এ কোনো ব্যক্তিগত পরিচয় তথ্য সংগ্রহ করি না৾`}},{id:`accuracy`,q:{en:`How accurate is the information?`,hi:`जानकारी कितनी सही है?`,mr:`माहिती किती अचूक आहे?`,ta:`தகவல் எவ்வளவு துல்லியமானது?`,te:`సమాచారం ఎంత ఖచ్చితమైనది?`,bn:`তথ্য কতটা নির্ভুল?`},a:{en:`Every scheme guide names the responsible authority, the applying office, expected timelines, and a link to the official website, so you can confirm before you act. Rules, document lists, and fees change — treat this as guidance to help you ask the right questions, not as a substitute for the official notification. When a guide and the official site disagree, the official site is correct.`,hi:`हर योजना गाइड में ज़िम्मेदार विभाग, आवेदन कार्यालय, अनुमानित समय और आधिकारिक वेबसाइट का लिंक दिया गया है, ताकि आप कार्रवाई से पहले पुष्टि कर सकें। नियम, दस्तावेज़ सूचियां और शुल्क बदलते रहते हैं — इसे आधिकारिक सूचना का विकल्प न मानें, बल्कि सही सवाल पूछने में मदद मानें। जब गाइड और आधिकारिक साइट में अंतर हो, तो आधिकारिक साइट सही है।`,mr:`प्रत्येक योजना मार्गदर्शनात जबाबदार विभाग, अर्ज कार्यालय, अपेक्षित वेळ आणि अधिकृत वेबसाइटचा दुवा दिला आहे, म्हणजे तुम्ही कृती करण्यापूर्वी खात्री करू शकता. नियम, कागदपत्र याद्या आणि शुल्के बदलतात — याला अधिकृत अधिसूचनेचा पर्याय मानू नका, तर योग्य प्रश्न विचारण्यास मदत माना. मार्गदर्शन आणि अधिकृत साइट यात फरक असल्यास अधिकृत साइट योग्य आहे.`,ta:`ஒவ்வொரு திட்ட வழிகாட்டலிலும் பொறுப்புக்குரிய அதிகாரம், விண்ணப்பிக்கும் அலுவலகம், எதிர்பார்க்கப்படும் கால அளவு மற்றும் அதிகாரப்பூர்வ இணையதள இணைப்பு கொடுக்கப்பட்டுள்ளது, அதனால் நீங்கள் செயல்படுவதற்கு முன் உறுதிப்படுத்தலாம். விதிகள், ஆவணப் பட்டியல்கள் மற்றும் கட்டணங்கள் மாறுகின்றன — இதை அதிகாரப்பூர்வ அறிவிப்பிற்கு மாற்றாக அல்ல, சரியான கேள்விகளைக் கேட்பதற்கான வழிகாட்டலாகக் கொள்ளவும். வழிகாட்டலும் அதிகாரப்பூர்வ தளமும் மாறுபட்டால் அதிகாரப்பூர்வ தளமே சரியானது.`,te:`ప్రతి పథక మార్గదర్శకంలో బాధ్యపైన అధికారం, దరఖాస్తు చేసే కార్యాలయం, అపేక్షించిన వ్యవధి మరియు అధికారిక వెబ్‌సైట్ లింక్ ఇవ్వబడ్డాయి, అందుకే మీరు చర్య తీసుకునే ముందు నిర్ధారించవచ్చు. నియమాలు, పత్ర జాబితాలు మరియు ఫీజులు మారతాయి — దీన్ని అధికారిక ప్రకటనకు ప్రత్యామ్నాయంగా భావించకండి, సరైన ప్రశ్నలు అడగడానికి మార్గదర్శకంగా తీసుకోండి. మార్గదర్శకం, అధికారిక సైట్ కలిసినప్పుడు అధికారిక సైటే సరైనది.`,bn:`প্রতিটি প্রকল্প নির্দেশিকায় দায়িত্বপ্রাপ্ত কর্তৃপক্ষ, আবেদনের দপ্তর, প্রত্যাশিত সময় এবং অফিসিয়াল ওয়েবসাইটের লিংক দেওয়া আছে, তাই আপনি কাজ করার আগে যাচাই করতে পারেন৾ নিয়ম, নথির তালিকা ও ফি পরিবর্তন হয় — এটিকে অফিসিয়াল নোটিফিকেশনের বিকল্প হিসেবে নয়, সঠিক প্রশ্ন জিজ্ঞাসা করতে সহায়তা হিসেবে বিবেচনা করুন৾ নির্দেশিকা ও অফিসিয়াল সাইটে মতভেদ হলে অফিসিয়াল সাইটই সঠিক৾`}},{id:`languages`,q:{en:`Which languages are available?`,hi:`कौन सी भाषाएं उपलब्ध हैं?`,mr:`कोणत्या भाषा उपलब्ध आहेत?`,ta:`எந்த மொழிகள் கிடைக்கின்றன?`,te:`ఏ భాషలు అందుబాటులో ఉన్నాయి?`,bn:`কোন ভাষাগুলি উপলব্ধ?`},a:{en:`Text guidance is available in 12 languages: English, Hindi, Marathi, Tamil, Telugu, Bengali, Gujarati, Kannada, Malayalam, Punjabi, Odia and Assamese. Voice is not available for every language — the Voice page tells you plainly when a language has no voice yet and offers the chat instead, rather than promising something that will not work. Where a guide has not been translated yet, you see English with a note naming the languages that are still missing.`,hi:`टेक्स्ट मार्गदर्शन 12 भाषाओं में उपलब्ध है: अंग्रेज़ी, हिन्दी, मराठी, तमिल, तेलुगु, बंगाली, गुजराती, कन्नड़, मलयालम, पंजाबी, ओडिया और असमिया। हर भाषा में आवाज़ उपलब्ध नहीं है — वॉयस पेज साफ़ बताता है कि किस भाषा में अभी आवाज़ नहीं है और उसके बजाय चैट देता है, ऐसा वादा नहीं करता जो काम न करे। जहाँ गाइड का अनुवाद अभी नहीं हुआ, वहाँ आपको अंग्रेज़ी और कौन सी भाषाएं अभी बाकी हैं, यह भी दिखाया जाता है।`,mr:`मजकूर मार्गदर्शन 12 भाषांत उपलब्ध आहे: इंग्रजी, हिंदी, मराठी, तमिल, तेलुगु, बंगाली, गुजराती, कन्नड, मलयाळम, पंजाबी, ओडिया आणि आसामी. प्रत्येक भाषेत आवाज उपलब्ध नाही — व्हॉयस पान स्पष्टपणे सांगते की कोणत्या भाषेत अद्याप आवाज नाही आणि त्याऐवजी चॅट देते, असे वचन देत नाही जे काम करणार नाही. जिथे मार्गदर्शनाचा अनुवाद अद्याप झालेला नाही, तिथे इंग्रजी आणि कोणत्या भाषा अद्याप बाकी आहेत हेही दिसते.`,ta:`உரை வழிகாட்டல் 12 மொழிகளில் கிடைக்கிறது: ஆங்கிலம், இந்தி, மராத்தி, தமிழ், தெலுங்கு, வங்காளம், குஜராத்தி, கன்னடம், மலையாளம், பஞ்சாபி, ஒடியா மற்றும் அசாமியா. ஒவ்வொரு மொழிக்கும் குரல் இல்லை — குரல் பக்கம் எந்த மொழிக்கு இன்னும் குரல் இல்லை என்பதை தெளிவாகச் சொல்லி, அதற்குப் பதிலாகச் சாட்டை வழங்குகிறது, செயல்படாத ஒன்றை வாக்குறுதிப்பதில்லை. வழிகாட்டல் மொழிபெயர்க்கப்படாத இடங்களில் ஆங்கிலம் காட்டப்படும், மேலும் எந்த மொழிகள் இன்னும் விடுபட்டுள்ளன என்பதையும் குறிப்பிடுகிறது.`,te:`పాఠ్య మార్గదర్శకం 12 భాషల్లో అందుబాటులో ఉంది: ఇంగ్లీష్, హిందీ, మరాఠీ, తమిళం, తెలుగు, బెంగాలీ, గుజరాతీ, కన్నడ, మలయాళం, పంజాబీ, ఒడియా మరియు అసమీయా. ప్రతి భాషకు వాయిస్ లేదు — వాయిస్ పేజీ ఏ భాషకు ఇంకా వాయిస్ లేదో స్పష్టంగా చెబుతుంది, దానికి బదులుగా చాట్‌ను అందిస్తుంది, పనిచేయని దానిని హామీ ఇవ్వదు. అనువాదం ఇంకా లేని చోట్ల ఇంగ్లీష్ కనిపిస్తుంది, ఏ భాషలు ఇంకా తప్పఉన్నాయో అనేది కూడా చెబుతుంది.`,bn:`লেখা নির্দেশিকা 12টি ভাষায় উপলব্ধ: ইংরেজি, হিন্দি, মারাঠি, তামিল, তেলুগু, বাংলা, গুজরাটি, কন্নড়, মালয়ালম, পাঞ্জাবি, ওড়িয়া এবং অসমীয়া৾ প্রতিটি ভাষায় ভয়েস নেই — ভয়েস পেজ স্পষ্টভাবে বলে কোন ভাষায় এখনো ভয়েস নেই এবং তার বদলে চ্যাট দেয়, কাজ না করা কিছুর প্রতিশ্রুতি দেয় না৾ যেখানে নির্দেশিকা অনূদিত হয়নি, সেখানে ইংরেজি এবং কোন ভাষাগুলি এখনো বাকি তা দেখানো হয়৾`}},{id:`submit`,q:{en:`Can I apply to a scheme through this app?`,hi:`क्या मैं इस ऐप से किसी योजना के लिए आवेदन कर सकता हूँ?`,mr:`मी या अ‍ॅपमूून कुठी योजनेसाठी अर्ज करू शकतो का?`,ta:`இந்தச் செயலியிலிருந்து ஏதேனும் திட்டத்திற்கு விண்ணப்பிக்க முடியுமா?`,te:`ఈ యాప్ ద్వారా ఏ పథకానికి దరఖాస్తు చేయగలనా?`,bn:`এই অ্যাপ থেকে কি কোনো প্রকল্পে আবেদন করা যায়?`},a:{en:`No, not yet. This version explains schemes and tells you where to apply, but it cannot submit anything to a government department, and it does not collect or store Aadhaar, PAN, bank details, or any identity document. Applying is still done through the official portal, the office, or a Common Service Centre. Form filling and document upload are planned for a later version.`,hi:`नहीं, अभी नहीं। यह संस्करण योजनाएं समझाता है और आवेदन कहाँ करें यह बताता है, लेकिन यह किसी सरकारी विभाग में कुछ भी जमा नहीं कर सकता, और न ही आधार, पैन, बैंक विवरण या कोई पहचान दस्तावेज़ जमा या संग्रहीत करता है। आवेदन अभी भी आधिकारिक पोर्टल, कार्यालय या कॉमन सर्विस सेंटर से ही होता है। फॉर्म भरना और दस्तावेज़ अपलोड बाद के संस्करण के लिए नियोजित हैं।`,mr:`नाही, अद्याप नाही. ही आवृत्ती योजनांचे स्पष्टीकरण करते आणि अर्ज कुठे करायचा ते सांगते, पण ती कोणत्याही सरकारी विभागाकडे काहीही सादर करू शकत नाही, आणि आधार, पॅन, बँक तपशील किंवा ओळखपत्र साठवत नाही. अर्ज अद्याप अधिकृत पोर्टल, कार्यालय किंवा सामान्य सेवा केंद्रामार्फतच करावा लागतो. फॉर्म भरणे आणि कागदपत्र अपलोड नंतरच्या आवृत्तीसाठी नियोजित आहेत.`,ta:`இல்லை, இன்னும் இல்லை. இந்தப் பதிப்பு திட்டங்களை விளக்கி எங்கு விண்ணப்பிக்க வேண்டும் என்பதைச் சொல்கிறது, ஆனால் எந்த அரசு அமைப்பிடத்திற்கும் எதுவும் சமர்ப்பிக்க முடியாது, ஆதார், பான், வங்கி விவரங்கள் அல்லது அடையாளச் சான்றிதழ்களையும் சேமிப்பதில்லை. விண்ணப்பம் இன்னும் அதிகாரப்பூர்வ போர்ட்டல், அலுவலகம் அல்லது கொமன் சர்விஸ் சென்டரில் மட்டுமே செய்யப்படுகிறது. படிவம் நிரப்புதல் மற்றும் ஆவணம் பதிவேற்றம் பின்னரையான பதிப்புகளுக்குத் திட்டமிடப்பட்டுள்ளன.`,te:`కాదు, ఇంకా కాదు. ఈ సంస్కరణ పథకాలను వివరిస్తుంది, ఎక్కడ దరఖాస్తు చేయాలో చెబుతుంది, కానీ ఏ ప్రభుత్వ విభాగానికీ ఏదీ సమర్పించలేదు, ఆధార్, పాన్, బ్యాంక్ వివరాలు లేదా గుర్తింపు పత్రాలను సేకరించదు లేదా నిల్వ చేయదు. దరఖాస్తు ఇప్పటికీ అధికారిక పోర్టల్, కార్యాలయం లేదా కామన్ సర్వీస్ సెంటర్‌లోనే చేయాలి. ఫారం నింపడం మరియు పత్రం అప్‌లోడ్ తర్వాతి సంస్కరణలకు ప్రణాళికాబద్ధం.`,bn:`না, এখনো না৾ এই সংস্করণ প্রকল্প ব্যাখ্যা করে এবং কোথায় আবেদন করতে হবে তা বলে, কিন্তু কোনো সরকারি বিভাগে কিছু জমা দিতে পারে না, এবং আধার, প্যান, ব্যাংক তথ্য বা পরিচয়পত্র সংগ্রহ বা সংরক্ষণ করে না৾ আবেদন এখনও অফিসিয়াল পোর্টাল, দপ্তর বা কমন সার্ভিস সেন্টারে করতে হয়৾ ফর্ম পূরণ ও নথি আপলোড পরবর্তী সংস্করণের পরিকল্পনায় আছে৾`}}],l={en:{title:`Talk to a person`,body:`If you are not comfortable using this app, or a guide was not enough, these are the official routes to a human being.`,unavailable:`Not configured for this deployment`,cscBody:`Common Service Centres in your district handle applications for most central schemes, and can help you fill forms.`},hi:{title:`किसी व्यक्ति से बात करें`,body:`अगर आपको यह ऐप उपयोग करने में कठिन लगे, या गाइड पर्याप्त न हो, तो ये किसी इंसान तक पहुंचने के आधिकारिक रास्ते हैं।`,unavailable:`इस परिनियोजन के लिए कॉन्फ़िगर नहीं किया गया`,cscBody:`आपके जिले के कॉमन सर्विस सेंटर अधिकांश केंद्रीय योजनाओं के आवेदन संभालते हैं और फॉर्म भरने में मदद करते हैं।`},mr:{title:`माणसाशी बोला`,body:`हा अ‍ॅप वापरायला तुम्हाला अडचण वाटत असेल, किंवा मार्गदर्शन पुरसे नाही, तर माणसापर्यंत पोहोचण्याचे अधिकृत मार्ग हे आहेत.`,unavailable:`या रिलीजसाठी कॉन्फिगर केलेले नाही`,cscBody:`तुमच्या जिल्ह्यातील सामान्य सेवा केंद्रे बहुतेक केंद्रीय योजनांचे अर्ज घेतात आणि फॉर्म भरण्यास मदत करतात.`},ta:{title:`ஒருவருடன் பேசுங்கள்`,body:`இந்தச் செயலியைப் பயன்படுத்துவது உங்களுக்கு சங்கடிக்காததாக இருந்தால், அல்லது வழிகாட்டல் போதாவிட்டால், ஒருவரை அணர்வதற்கான இவை அதிகாரப்பூர்வ வழிகள்.`,unavailable:`இந்த வரிசையில் அமைக்கப்படவில்லை`,cscBody:`உங்கள் மாவட்டத்தின் கொமன் சர்விஸ் சென்டர்கள் பெரும்பாலான மத்திய திட்ட விண்ணப்பங்களைக் கையாள்கின்றன, படிவங்களை நிரப்ப உதவுகின்றன.`},te:{title:`ఒకరితో మాట్లాడండి`,body:`ఈ యాప్ వాడటం మీకు సౌకర్యంగా లేకపోతే, లేదా మార్గదర్శకం సరిపోదంటే, ఒకరిని చేరుకునే అధికారిక మార్గాలు ఇవి.`,unavailable:`ఈ అమ్ప్రకేషన్ కోసం కన్ఫిగర్ చేయలేదు`,cscBody:`మీ జిల్లాలోని కామన్ సర్వీస్ సెంటర్లు ఎక్కువ ప్రధాన పథక దరఖాస్తులను స్వీకరిస్తాయి, ఫారాలు నింపడంలో సహాయం చేస్తాయి.`},bn:{title:`একজন মানুষের সাথে কথা বলুন`,body:`যদি এই অ্যাপ ব্যবহার করা আপনার কষ্ট হয়, বা নির্দেশিকা যথেষ্ট না হয়, তাহলে একজন মানুষের কাছে পৌঁছানোর সরকারি মার্গগুলি এগুলি।`,unavailable:`এই ডিপ্লয়মেন্টের জন্য কনফিগার করা হয়নি`,cscBody:`আপনার জেলার কমন সার্ভিস সেন্টারগুলি বেশিরভাগ কেন্দ্রীয় প্রকল্পের আবেদন গ্রহণ করে এবং ফর্ম পূরণে সাহায্য করে।`}};function u(){let{language:e}=n(),u=l[e.code]||l.en,d=!!(o.tollFree.value||o.whatsapp.digits||o.csc.value);return(0,s.jsxs)(`div`,{className:`max-w-3xl mx-auto px-4 py-12`,children:[(0,s.jsxs)(`header`,{className:`mb-10`,children:[(0,s.jsx)(`h1`,{className:`font-display text-3xl text-ink mb-2`,children:`Help`}),(0,s.jsx)(`p`,{className:`text-ink-2 text-sm`,children:`Answers to the questions people actually ask, and how to reach a human.`})]}),(0,s.jsx)(`div`,{className:`space-y-4`,id:`faq`,children:c.map(t=>(0,s.jsx)(a,{title:r(t.q,e.code),children:(0,s.jsx)(`p`,{children:r(t.a,e.code)})},t.id))}),(0,s.jsxs)(`section`,{id:`contact`,className:`mt-12`,children:[(0,s.jsx)(`h2`,{className:`font-display text-2xl text-ink mb-2`,children:u.title}),(0,s.jsx)(`p`,{className:`text-ink-2 text-sm mb-6`,children:u.body}),!d&&(0,s.jsx)(i,{variant:`outlined`,className:`p-5 mb-4 border-mustard/40 bg-mustard/5`,children:(0,s.jsx)(`p`,{className:`text-sm text-mustard-2`,children:u.unavailable})}),(0,s.jsxs)(`div`,{className:`space-y-3`,children:[o.tollFree.value&&(0,s.jsxs)(i,{className:`p-4 flex items-center gap-4`,children:[(0,s.jsx)(`span`,{className:`text-2xl shrink-0`,"aria-hidden":`true`,children:`📞`}),(0,s.jsxs)(`div`,{className:`min-w-0`,children:[(0,s.jsx)(`p`,{className:`text-xs text-ink-3`,children:r(o.tollFree.label,e.code)}),(0,s.jsx)(`a`,{href:`tel:${o.tollFree.value}`,className:`text-forest hover:underline font-medium`,children:o.tollFree.value})]})]}),o.whatsapp.digits&&(0,s.jsxs)(i,{className:`p-4 flex items-center gap-4`,children:[(0,s.jsx)(`span`,{className:`text-2xl shrink-0`,"aria-hidden":`true`,children:`💬`}),(0,s.jsxs)(`div`,{className:`min-w-0`,children:[(0,s.jsx)(`p`,{className:`text-xs text-ink-3`,children:r(o.whatsapp.label,e.code)}),(0,s.jsx)(`a`,{href:`https://wa.me/${o.whatsapp.digits}`,target:`_blank`,rel:`noopener noreferrer`,className:`text-forest hover:underline font-medium`,children:o.whatsapp.value})]})]}),o.csc.value&&(0,s.jsxs)(i,{className:`p-4 flex items-start gap-4`,children:[(0,s.jsx)(`span`,{className:`text-2xl shrink-0`,"aria-hidden":`true`,children:`🏢`}),(0,s.jsxs)(`div`,{className:`min-w-0`,children:[(0,s.jsx)(`p`,{className:`text-xs text-ink-3`,children:r(o.csc.label,e.code)}),(0,s.jsx)(`p`,{className:`font-medium`,children:o.csc.value}),(0,s.jsx)(`p`,{className:`text-xs text-ink-3 mt-1`,children:u.cscBody})]})]})]})]}),(0,s.jsx)(`section`,{id:`privacy`,className:`mt-12`,children:(0,s.jsxs)(i,{variant:`accent`,className:`p-5`,children:[(0,s.jsx)(`h2`,{className:`font-medium text-ink mb-2`,children:`About this version`}),(0,s.jsx)(`p`,{className:`text-sm text-ink-2`,children:`Sahayak Seva explains schemes. It cannot submit applications, and it does not collect identity documents. Always complete your application on the official portal, at the office, or through a Common Service Centre.`}),(0,s.jsx)(`p`,{className:`text-xs text-ink-3 mt-3`,children:`Not an official government website. Guidance only — verify on official portals before you act.`}),(0,s.jsx)(t,{to:`/sync`,className:`inline-block mt-3 text-sm text-forest hover:underline min-h-[36px]`,children:`See what is stored on this device`})]})})]})}export{u as default};